Script:
TenantDetailsManagement = {
	init: async function (app, container, tenant) {
		app = app || session.app;
		container = container || $(".component[name=TenantDetailsManagement]");
		api.addToMetaCache([
			{
				"Name": "B2B",
				"Types": [
					[meta[B2B/Company]],
					[meta[B2B/Address]]
				]
			}
		]);

		if (!tenant) {
			return;
		}

		var companyData = {
			"Name": "",
			"ContactEmailAddress": null,
			"ContactPhoneNumber": null,
			"WebsiteUrl": null,
			"DateTradingEnabled": "",
			"IsVerified": false,
			"Payees": [],
			"Address": {
				"CountryId": "",
				"PoBox": "",
				"Line1": "",
				"Line2": "",
				"ZipOrPostalCode": "",
				"TownOrCity": "",
				"StateOrProvince": "",
			},
			"References": []
		};

		await api.get("DMS/CRM/" + tenant.Id + "/companyData.json")
			.then((sub) => companyData = sub)
			.catch(async (_) => await api.put("DMS/CRM/" + tenant.Id + "/companyData.json", companyData));

		var g = new WritableDetailView($("[name=companyDetails]"), {data: companyData});

		g.fields =
			model.propertiesFor("B2B/Company", ["Name", "ContactPhoneNumber", "ContactEmailAddress", "WebsiteUrl"])
				.concat(model.propertiesFor("B2B/Address", ["PoBox", "Line1", "Line2", "TownOrCity", "StateOrProvince", "ZipOrPostalCode", "CountryId"]).map(p => {
					p.field = "Address." + p.field;
					return p;
				}));

		g.fields = g.fields.concat([{field: "ClientType", title: "[resource_displayname[clienttype]]"}]);

		g.init();
		$("input[name=ClientType]", g.detailElement).kendoDropDownList({
			innerWidth: "100%",
			optionLabel: "Please select...",
            dataSource: [
				"[resource_displayname[buyer]]",
				"[resource_displayname[supplier]]",
				"[resource_displayname[funder]]"
			]
        });;

		var referencesGrid = new GridWidget($("[name=references]", container), { data: companyData.References, pageSize: 10 });
		referencesGrid.groupable = false;
		referencesGrid.pageable = false;
		referencesGrid.filterable = true;
		referencesGrid.editable = true;
		referencesGrid.scrollable = false;
		referencesGrid.dataBound = function (e) {
			$("[name=remove]", referencesGrid.gridElement).off("click").on("click", (e) => TenantDetailsManagement.removeReference(e, referencesGrid));
		};
		referencesGrid.commands.push({ name: "remove", icon: "k-i-trash", text: "[resource_displayname[remove]]" });
		referencesGrid.toolbar = "<button name='add'><span class='k-icon k-i-plus'></span>[resource_displayname[add]]</button>";
		referencesGrid.columns = [
			{ field: "SystemId", title: "[resource_shortdisplayname[systemid]]" },
			{ field: "Value", title: "[resource_shortdisplayname[value]]" },
		];
		await referencesGrid.init();
		$("[name=add]", referencesGrid.gridElement).on("click", (e) => TenantDetailsManagement.newReference(e, referencesGrid));
		$("[name=save]", container).off("click").on("click", async (e) => await TenantDetailsManagement.save(e, g.data.toJSON(), tenant, referencesGrid));
	},

	save: async function (e, companyData, tenant, referencesGrid) {
        e.preventDefault();
		companyData.References = referencesGrid.dataSource().data();
        await api.update("DMS/CRM/" + tenant.Id + "/companyData.json", companyData).then(() => {
            notification.success("[resource_displayname[saved]]");
        }).catch((err) => error(err));
    },

	newReference: async function (e, referencesGrid) {
		e.preventDefault();
		referencesGrid.dataSource().add({SystemId: "", Value: ""});
	},

    removeReference: async function (e, referencesGrid) {
        e.preventDefault();
        var item = referencesGrid.kendoObject.dataItem($(e.currentTarget).closest("tr"));
		referencesGrid.dataSource().remove(item);
    },
}
